def rank_matrix(arr):
    """Row-wise Spearman ranks -> (T,15), NaN where invalid. Vectorized per row."""
    out = np.full(arr.shape, np.nan)
    T = arr.shape[0]
    for t in range(T):
        row = arr[t]
        m = np.isfinite(row)
        n = m.sum()
        if n >= 8:
            r = np.full(15, np.nan)
            r[m] = (pd.Series(row[m]).rank().values)
