"""Round 20 novel factor screen (miner_2) - fresh ideas NOT in evicted/quarantine/failed lists.

Fresh ideas:
- world_beta_60: beta vs equal-weight cross-asset index (global risk, distinct from SPX beta)
- world_rel_mom_20: 20d momentum minus cross-sectional median (whole-universe relative strength)
- overnight_ret_20 / intraday_ret_20 / intraday_vol_20: open-based session splits (data has open!)
- trend_r2_20: R^2 of 20d linear trend fit (trend consistency)
- gk_vol_z_20_60: Garman-Klass intraday vol z-score (uses high/low/open/close)
- close_typical_20: close vs typical price (H+L+C)/3
- newhigh_slope_20: max(high,20)/max(high,60)-1 new-high acceleration
- wti_beta_cond_60x20 / copper_beta_cond_60x20: commodity beta x commodity momentum
- dollar_vol_trend_20_60: volume trend (20d vs 60d dollar volume)
- max_gap_20: max overnight gap magnitude
- hsi_ndx_beta_20: beta to HSI/NDX ratio (China-vs-tech rotation)
- xau_beta_20: 20d gold beta (short-window variant of failed 60d)
- sx5e_rel_mom_20 / hsi_rel_mom_20: relative momentum family extension (spx/gold rel mom passed)

Validates vs full EFFECTIVE library (signal artifacts on canonical grid, shape-matched
like the deterministic gate: artifacts whose shape != (len(grid),15) are skipped).
Admission: |IC|>=0.007, |ICIR|>=0.084 (h=10), rho<0.5.
"""
import sys, time, json, warnings
warnings.filterwarnings('ignore')
sys.path.insert(0, 'scripts')
import numpy as np
import pandas as pd
from pathlib import Path
from factor_common import (load_prices, factor_to_panel, validate_factor,
                           canonical_grid, signal_matrix, WATCHLIST)

t0 = time.time()
prices = load_prices(days=2000)
grid = canonical_grid(prices)
print(f'prices={len(prices)} grid={len(grid)} {grid.min().date()}..{grid.max().date()}', flush=True)

# ---- library: effective factors with signal artifacts on the SAME grid shape ----
lib = {}
for p in sorted(Path('factors').glob('*.json')):
    if p.name.endswith('.bak') or 'deprecated' in p.name or 'ensemble' in p.name:
        continue
    try:
        payload = json.loads(p.read_text(encoding='utf-8'))
    except Exception:
        continue
    if payload.get('validation', {}).get('status') != 'EFFECTIVE':
        continue
    art = payload.get('signal_artifact')
    art_path = p.parent / str(art) if art else None
    if art_path is not None and art_path.exists():
        arr = np.load(art_path, allow_pickle=False)
        if arr.shape == (len(grid), len(WATCHLIST)):
            lib[payload['factor_id']] = arr
print(f'library factors (shape-matched): {len(lib)} {sorted(lib.keys())}', flush=True)

def rank_matrix(arr):
    out = np.full(arr.shape, np.nan)
    for t in range(arr.shape[0]):
        row = arr[t]
        m = np.isfinite(row)
        n = int(m.sum())
        if n >= 8:
            r = np.full(arr.shape[1], np.nan)
            r[m] = pd.Series(row[m]).rank().values
            out[t] = r
    return out

lib_rank = {fid: rank_matrix(arr) for fid, arr in lib.items()}

def lib_max_corr(panel):
    arr = signal_matrix(panel, grid)
    cand = rank_matrix(arr)
    best, best_id = 0.0, None
    for fid, lr in lib_rank.items():
        corrs = []
        for t in range(len(grid)):
            a, b = cand[t], lr[t]
            m = np.isfinite(a) & np.isfinite(b)
            if m.sum() >= 8:
                a2, b2 = a[m], b[m]
                sa, sb = a2.std(), b2.std()
                if sa > 1e-12 and sb > 1e-12:
                    corrs.append(float(np.corrcoef(a2, b2)[0, 1]))
        if corrs:
            r = float(np.mean(corrs))
            if abs(r) > best:
                best, best_id = abs(r), fid
    return best, best_id

# ---- helpers ----
def bench_ret(sym):
    return prices[sym]['close'].pct_change()

def rolling_beta(asset_df, bench_series, window, min_obs=30, bench_is_yield=False):
    r = asset_df['close'].pct_change()
    b = bench_series.diff() if bench_is_yield else bench_series
    z = pd.concat([r.rename('r'), b.rename('b')], axis=1).dropna()
    cov = z['r'].rolling(window, min_periods=min_obs).cov(z['b'])
    var = z['b'].rolling(window, min_periods=min_obs).var()
    return (cov / var).reindex(z.index)

def mom_20(sym):
    df = prices[sym]
    return df['close'] / df['close'].shift(20) - 1.0

# equal-weight world return
world_ret = pd.concat([bench_ret(s).rename(s) for s in WATCHLIST], axis=1).mean(axis=1)

# ---- candidate factor functions ----
def f_world_beta_60(df, s):
    return rolling_beta(df, world_ret, 60)

def f_world_rel_mom_20(df, s):
    mine = df['close'] / df['close'].shift(20) - 1.0
    xs = pd.concat([prices[x]['close'].pct_change(20) for x in WATCHLIST], axis=1)
    med = xs.median(axis=1)
    return (mine - med).reindex(mine.index)

def f_overnight_ret_20(df, s):
    on = df['open'] / df['close'].shift(1) - 1.0
    return on.rolling(20, min_periods=10).mean()

def f_intraday_ret_20(df, s):
    intr = df['close'] / df['open'] - 1.0
    return intr.rolling(20, min_periods=10).mean()

def f_intraday_vol_20(df, s):
    intr = df['close'] / df['open'] - 1.0
    return intr.rolling(20, min_periods=10).std()

def f_trend_r2_20(df, s):
    lc = np.log(df['close'])
    def r2(win):
        if len(win) < 10 or win.std() == 0:
            return np.nan
        x = np.arange(len(win))
        return float(np.corrcoef(x, win)[0, 1] ** 2)
    return lc.rolling(20, min_periods=10).apply(r2, raw=True)

def f_gk_vol_z_20_60(df, s):
    o, h, l, c = df['open'], df['high'], df['low'], df['close']
    gk = np.sqrt(0.5 * np.log(h / l) ** 2 - (2 * np.log(2) - 1) * np.log(c / o) ** 2)
    v20 = gk.rolling(20, min_periods=10).mean()
    mu = v20.rolling(60, min_periods=30).mean()
    sd = v20.rolling(60, min_periods=30).std()
    return ((v20 - mu) / sd.replace(0, np.nan))

def f_close_typical_20(df, s):
    tp = (df['high'] + df['low'] + df['close']) / 3.0
    return (df['close'] / tp - 1.0).rolling(20, min_periods=10).mean()

def f_newhigh_slope_20(df, s):
    h20 = df['high'].rolling(20).max()
    h60 = df['high'].rolling(60).max()
    return (h20 / h60 - 1.0)

def f_wti_beta_cond_60x20(df, s):
    if 'WTI' not in prices:
        return None
    b = rolling_beta(df, bench_ret('WTI'), 60)
    return (b * mom_20('WTI')).reindex(b.index)

def f_copper_beta_cond_60x20(df, s):
    if 'COPPER' not in prices:
        return None
    b = rolling_beta(df, bench_ret('COPPER'), 60)
    return (b * mom_20('COPPER')).reindex(b.index)

def f_dollar_vol_trend_20_60(df, s):
    dv = df['close'] * df['volume'].astype(float)
    v20 = dv.rolling(20, min_periods=10).mean()
    v60 = dv.rolling(60, min_periods=30).mean()
    return (v20 / v60 - 1.0)

def f_max_gap_20(df, s):
    gap = (df['open'] / df['close'].shift(1) - 1.0).abs()
    return gap.rolling(20, min_periods=10).max()

def f_hsi_ndx_beta_20(df, s):
    if 'HSI' not in prices or 'NDX' not in prices:
        return None
    ratio = prices['HSI']['close'] / prices['NDX']['close']
    return rolling_beta(df, ratio.pct_change(), 20, min_obs=12)

def f_xau_beta_20(df, s):
    if 'XAU' not in prices:
        return None
    return rolling_beta(df, bench_ret('XAU'), 20, min_obs=12)

def f_sx5e_rel_mom_20(df, s):
    if 'SX5E' not in prices:
        return None
    mine = df['close'] / df['close'].shift(20) - 1.0
    ref = prices['SX5E']['close'] / prices['SX5E']['close'].shift(20) - 1.0
    return (mine - ref).reindex(mine.index)

def f_hsi_rel_mom_20(df, s):
    if 'HSI' not in prices:
        return None
    mine = df['close'] / df['close'].shift(20) - 1.0
    ref = prices['HSI']['close'] / prices['HSI']['close'].shift(20) - 1.0
    return (mine - ref).reindex(mine.index)

CANDIDATES = [
    ('world_beta_60', f_world_beta_60),
    ('world_rel_mom_20', f_world_rel_mom_20),
